CREATE OR REPLACE FUNCTION lr_serverless_aws_us_catalog.bricksurance_claim.fn_outstanding_reserve(in_claim_number STRING COMMENT 'Claim number, e.g. CLM-2026-000001.')
RETURNS DECIMAL(18,2)
COMMENT 'The current outstanding case reserve on a claim, derived live as the sum of signed reserve movements - never a stored balance. Returns: Outstanding reserve in the claim currency; 0 when fully released.'
RETURN (SELECT COALESCE(SUM(ct.amount), 0)
 FROM lr_serverless_aws_us_catalog.bricksurance_claim.claim_transaction ct
